    background: linear-gradient(145deg, #b58b28 0, #d4a73f 45%, #966b12 100%)
  }
</style>
<var>
  <p></p>
  <div style="font-family:-apple-system,system-ui,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;color:#1e293b;width:95%;max-width:750px;margin:20px auto;line-height:1.3">
    <div style="text-align:center">
      <div style="margin-bottom:10px">
        <div style="display:inline-flex;align-items:center;gap:8px;padding:6px 18px;border-radius:8px;font-size:15px;letter-spacing:1.6px;text-transform:uppercase;font-weight:700;background:rgba(0,0,0,.35);color:#fff;border:1px solid #fc3">WELCOME BONUS</div>
        <div style="margin-top:12px;font-size:clamp(26px,8vw,36px);font-weight:900;letter-spacing:-.5px;color:#fff;text-shadow:1px 1px 0 #000,2px 2px 0 #000,2px 2px 0 #000,1px 1px 0 #000">100% <span style="font-size:16px;font-weight:400;opacity:.9"></span>
        </div>
      </div>
      <div style="background:rgba(0,0,0,.35);border-radius:8px;padding:16px;border:1px solid #fc3">
        <div style="display:flex;margin-bottom:14px">
          <div style="flex:1;text-align:center;border-right:1px solid rgba(255,204,51,.4)">
            <div style="font-size:10px;text-transform:uppercase;margin-bottom:4px;font-weight:700;color:#ffdd4d">MIN DEPOSIT</div>
            <div style="font-size:13px;font-weight:900;color:#fff">$50</div>
          </div>
          <div style="flex:1;text-align:center;border-right:1px solid rgba(255,204,51,.4)">
            <div style="font-size:10px;text-transform:uppercase;margin-bottom:4px;font-weight:700;color:#ffdd4d">TURNOVER</div>
            <div style="font-size:13px;font-weight:900;color:#fff">X4</div>
          </div>
          <div style="flex:1;text-align:center">
            <div style="font-size:10px;text-transform:uppercase;margin-bottom:4px;font-weight:700;color:#ffdd4d">MAX WITHDRAW</div>
            <div style="font-size:13px;font-weight:900;color:#fff">$1888</div>
          </div>
        </div>
        <div style="display:flex;border-top:1px solid rgba(255,204,51,.3);padding-top:14px">
          <div style="flex:1;text-align:center;border-right:1px solid rgba(255,204,51,.4)">
            <div style="font-size:10px;text-transform:uppercase;margin-bottom:4px;font-weight:700;color:#ffdd4d">CLAIM LIMIT</div>
            <div style="font-size:13px;font-weight:900;color:#fff">ONCE</div>
          </div>
          <div style="flex:1;text-align:center">
            <div style="font-size:10px;text-transform:uppercase;margin-bottom:4px;font-weight:700;color:#ffdd4d">ALLOWED GAME</div>
            <div style="font-size:13px;font-weight:900;color:#fff">ALL SLOT GAMES</div>
          </div>
        </div>
      </div>
    </div>
    <div style="display:flex;gap:8px;margin:3px 0 5px 0"></div>
    <div style="padding:14px;margin-bottom:1px">
      <div style="font-size:12px;color:#fff;font-weight:600;margin-bottom:8px;display:flex;align-items:center;gap:8px">
        <span style="color:#ffdd4d;font-size:16px">✓</span>Players name must exactly match the name on the bank account.
      </div>
      <div style="font-size:12px;color:#fff;font-weight:600;margin-bottom:8px;display:flex;align-items:center;gap:8px">
        <span style="color:#ffdd4d;font-size:16px">✓</span>This bonus cannot be combined with any other promotions.
      </div>
      <div style="font-size:12px;color:#fff;font-weight:600;margin-bottom:10px;display:flex;align-items:center;gap:8px">
        <span style="color:#ffdd4d;font-size:16px">✓</span>This bonus can only be claimed once per account.
      </div>
      <div style="font-size:12px;color:#fff;font-weight:600;margin-bottom:10px;display:flex;align-items:center;gap:8px">
        <span style="color:#d91e1e;font-size:16px">X</span>Buying or saving free game, all credit will be forfeited.
      </div>
    </div>
    <div style="border-top:1px solid #FFCC33;padding-top:15px">
      <div style="font-size:14px;font-weight:900;color:#fff;text-transform:uppercase;margin-bottom:10px">Terms & Conditions</div>
      <div style="font-size:11px;color:#fff;line-height:1.6">
        <b style="color:#fff">• Claim Bonus Before Entering Any Game</b>
        <br>
        <b style="color:#fff">• Registered Name Must Be An Exact Match To Your Bank Account Details.</b>
        <br>
        <b style="color:#fff">• Limited To 1 Account / IP Per Person. Multiple Entries Are Strictly Prohibited.</b>
          <br>
        <b style="color:#fff">• Game Rules: ALL SLOT Games Only. Any Other Play Will Result In Forfeiture.</b>
          <br>
        <b style="color:#fff">•The Maximum Payout Is $1888. Any Extra Balance Will Be Forfeited.</b>
      </div>
    </div>
    <div style="margin-top:8px;text-align:center">
      <div style="border-top:1px solid #fc3;padding-top:10px"></div>
      <div style="font-size:11px;color:#7dcf1d;font-weight:600;margin-bottom:8px">
        <span style="color:#fff;font-size:8px">General VV88AU Rules remain in effect. Unusual wagering activity will cause an automatic reset of your account balance to zero.</span>
      </div>
    </div>
  </div>
  <p></p>
</var>
<style>
  @keyframes fadeInUp {
    0% {
      opacity: 0;
      transform: translateY(30px)
    }

    100% {
      opacity: 1;
      transform: translateY(0)
    }
  }

  @keyframes slideIn {
    0% {
      width: 0
    }

    100% {
      width: 40%
    }
  }

  div .div:hover {
    transform: translateX(10px);
    color: #7a56e0
  }

  .term:hover {
    transform: scale(1.05);
    box-shadow: 0 0 15px #d9d9d9
  }

  .term:hover .term-text {
    color: #200202;
    font-size: 1rem
  }

  .term-icon {
    animation: iconPulse 2s infinite ease-in-out
  }

  @keyframes iconPulse {
    0% {
      transform: scale(1)
    }

    50% {
      transform: scale(1.2)
    }

    100% {
      transform: scale(1)
    }
  }

  .border-animation {
    position: absolute;
    width: 100%;
    height: 100%;
    top: 0;
    left: 0;
    border-radius: 30px;
    box-shadow: 0 0 20px #d9d9d9, 0 0 30px #d9d9d9 inset;
    border: 4px solid transparent;
    animation: glowingBorder 3s infinite alternate, rotateBorder 5s infinite linear
  }

  @keyframes glowingBorder {
    0% {
      box-shadow: 0 0 15px #d9d9d9, 0 0 25px #d9d9d9 inset
    }

    100% {
      box-shadow: 0 0 25px #d9d9d9, 0 0 40px #d9d9d9 inset
    }
  }

  @keyframes rotateBorder {
    0% {
      transform: rotateY(0)
    }

    100% {
      transform: rotateY(90deg)
    }
  }

  .border-animation2 {
    position: absolute;
    width: 100%;
    height: 100%;
    top: 0;
    left: 0;
    border-radius: 30px;
    box-shadow: 0 0 20px #d9d9d9, 0 0 30px #d9d9d9 inset;
    border: 4px solid transparent;
    animation: glowingBorder2 3s infinite alternate, rotateBorder2 3s infinite linear
  }

  @keyframes glowingBorder2 {
    0% {
      box-shadow: 0 0 15px #d9d9d9, 0 0 25px #d9d9d9 inset
    }

    100% {
      box-shadow: 0 0 25px #d9d9d9, 0 0 40px #d9d9d9 inset
    }
  }

  @keyframes rotateBorder2 {
    0% {
      transform: rotateX(0)
    }

    100% {
      transform: rotateX(180deg)
    }
  }

  @keyframes circlePulse {

    0%,
    100% {
      transform: scale(1);
      opacity: .7
    }

    50% {
      transform: scale(1.5);
      opacity: .3
    }
  }

  @keyframes rotateHorizontal {
    0% {
      transform: rotateY(0)
    }

    100% {
      transform: rotateY(360deg)
    }
  }

  @keyframes fadeInBackground {
    0% {
      background-position: 50% 50%;
      background-size: 80%
    }

    100% {
      background-position: 100% 50%;
      background-size: 110%
    }
  }

  @keyframes panelSlideIn {
    0% {
      opacity: 0;
      transform: translateY(50px)
    }

    100% {
      opacity: 1;
      transform: translateY(0)
    }
  }

  @keyframes fadeInDown {
    0% {
      opacity: 0;
      transform: translateY(-50px)
    }

    100% {
      opacity: 1;
      transform: translateY(0)
    }
  }

  @keyframes slideInLeft {
    0% {
      opacity: 0;
      transform: translateX(-50px)
    }

    100% {
      opacity: 1;
      transform: translateX(0)
    }
  }

  @keyframes slideInRight {
    0% {
      opacity: 0;
      transform: translateX(50px)
    }

    100% {
      opacity: 1;
      transform: translateX(0)
    }
  }

  @keyframes fadeInUp {
    0% {
      opacity: 0;
      transform: translateY(20px)
    }

    100% {
      opacity: 1;
      transform: translateY(0)
    }
  }

  @keyframes zoomIn {
    0% {
      opacity: 0;
      transform: scale(.8)
    }

    100% {
      opacity: 1;
      transform: scale(1)
    }
  }

  @keyframes bounceIn {
    0% {
      opacity: 0;
      transform: scale(.8)
    }

    50% {
      transform: scale(1.2)
    }

    100% {
      opacity: 1;
      transform: scale(1)
    }
  }

  @keyframes pulseGlow {

    0%,
    100% {
      text-shadow: 0 0 20px #8b0000, 0 0 30px #98fb98
    }

    50% {
      text-shadow: 0 0 40px #98fb98, 0 0 60px #98fb98
    }
  }

  @media (max-width:768px) {
    h1 {
      font-size: 24px
    }

    p,
    ul li {
      font-size: 14px
    }

    img {
      max-width: 300px
    }
  }

  @media (max-width:768px) {
    div[style*="max-width: 700px"] {
      max-width: 90%;
      margin: 20px auto;
      padding: 15px
    }

    h1 {
      font-size: 24px !important
    }

    marquee {
      font-size: 18px !important
    }

    p {
      font-size: 18px !important
    }

    table td {
      padding: 10px !important;
      font-size: 16px !important
    }

    .div {
      font-size: 16px !important;
      padding-left: 15px !important
    }

    div[style*="position: absolute"] {
      width: 120px !important;
      height: 120px !important;
      top: -60px !important;
      left: -60px !important;
      right: -60px !important
    }
  }

  @media (max-width:480px) {
    h1 {
      font-size: 20px !important
    }

    marquee {
      font-size: 16px !important
    }

    p {
      font-size: 16px !important
    }

    table td {
      font-size: 14px !important
    }

    .div {
      font-size: 14px !important
    }

    div[style*="position: absolute"] {
      width: 100px !important;
      height: 100px !important;
      top: -50px !important;
      left: -50px !important;
      right: -50px !important
    }
  }

  td:hover {
    transform: scale(1.1) rotateY(15deg) translateZ(20px);
    box-shadow: 0 20px 50px rgba(192, 0, 255, .9);
    filter: brightness(1.3)
  }

  td:hover>div {
    opacity: 1
  }

  div:hover>div {
    opacity: 1
  }

  td {
    cursor: pointer
  }

  td:hover {
    animation: neonPulse 1s infinite
  }

  @media (min-width:768px) {
    div {
      perspective: 1000px
    }

    td {
      transform-style: preserve-3d;
      transition: transform .5s ease
    }

    td:hover {
      transform: translateZ(30px)
    }
  }
</style>","DescQuillEditor":{"ops":[{"insert":"
